local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, 'Greetings and Banor with you, |PLAYERNAME|!')
npcHandler:setMessage(MESSAGE_FAREWELL, 'PRAISE TO BANOR!')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'PRAISE TO BANOR!')
keywordHandler:addKeyword({'cult'}, StdModule.say, {npcHandler = npcHandler, text = 'We know only little about them. Kaine and his fallen knights were joined by criminal scum and remaining forces of darkness that escaped us. They were joined by some ominous dark monks.'})
keywordHandler:addKeyword({'honor'}, StdModule.say, {npcHandler = npcHandler, text = 'Only those who live a life of bravery, honor, and piety may join our sacred order.'})
keywordHandler:addKeyword({'weapon'}, StdModule.say, {npcHandler = npcHandler, text = 'Look for Willard, our local blacksmith.'})
keywordHandler:addKeyword({'tyrant'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'monster'}, StdModule.say, {npcHandler = npcHandler, text = 'We cleansed the south of any major enemy, but watch out while travelling the north.'})
keywordHandler:addKeyword({'eremo'}, StdModule.say, {npcHandler = npcHandler, text = 'Eremo is a very wise man. I visit him sometimes on his little island near Edron. Just ask a fisherman for a passage.'})
keywordHandler:addKeyword({'ferumbras'}, StdModule.say, {npcHandler = npcHandler, text = 'He searched something in the north of the isle years ago. Probably he needed something from the forbidden ruins. He was chased and fought by the troops of General Benjamin.'})
keywordHandler:addKeyword({'news'}, StdModule.say, {npcHandler = npcHandler, text = 'Nothing new from the north.'})
keywordHandler:addKeyword({'monk'}, StdModule.say, {npcHandler = npcHandler, text = 'We don\'t know if they came here or already hid in the ruins as we arrived. Maybe they seduced Kaine or Agaltha, maybe they were theirs for years.'})
keywordHandler:addKeyword({'castle'}, StdModule.say, {npcHandler = npcHandler, text = 'The castle was built on elder foundations we found on this isle.'})
keywordHandler:addKeyword({'sell'}, StdModule.say, {npcHandler = npcHandler, text = 'Are you suggesting I am corruptible?'})
keywordHandler:addKeyword({'cormaya'}, StdModule.say, {npcHandler = npcHandler, text = 'It is a peaceful isle next to Edron with a nice village. There, you should visit the wonderful garden.'})
keywordHandler:addKeyword({'falk'}, StdModule.say, {npcHandler = npcHandler, text = 'A promising young fellow.'})
keywordHandler:addKeyword({'kaine'}, StdModule.say, {npcHandler = npcHandler, text = 'He was my second in command. After learning about the forbidden ruins, he, the priestess Agaltha, and their followers freed the criminals we brought here as workers and headed to the north.'})
keywordHandler:addKeyword({'amanda'}, StdModule.say, {npcHandler = npcHandler, text = 'I think this nun might be a bit young for this position, but I won\'t question the decisions of the church of Banor\'s Blood.'})
keywordHandler:addKeyword({'cyclop'}, StdModule.say, {npcHandler = npcHandler, text = 'They live in an underground city, known as cyclopolis in the north of the isle. Constantly forging weapons for the servants of darkness.'})
keywordHandler:addKeyword({'zathroth'}, StdModule.say, {npcHandler = npcHandler, text = 'Do not mention the name of the cursed one!'})
keywordHandler:addKeyword({'willard'}, StdModule.say, {npcHandler = npcHandler, text = 'When he was young, Willard served in the royal army.'})
keywordHandler:addKeyword({'kazordoon'}, StdModule.say, {npcHandler = npcHandler, text = 'Now and then a dwarf comes to this isle. Most behave secretive about their reason to come here. As far as I can tell they are looking for some dwarfish artifact which was lost in ancient times.'})
keywordHandler:addKeyword({'carlin'}, StdModule.say, {npcHandler = npcHandler, text = 'I belong to a sacred order and don\'t bother about mundane politics.'})
keywordHandler:addKeyword({'king'}, StdModule.say, {npcHandler = npcHandler, text = 'LONG LIVE THE KING!'})
keywordHandler:addKeyword({'benjamin'}, StdModule.say, {npcHandler = npcHandler, text = 'He and his men fought against Ferumbras somewhere in the north of this isle, long before there were even plans of a colony. Only old Ben returned alive from the battle, but his mind was broken.'})
keywordHandler:addKeyword({'brog'}, StdModule.say, {npcHandler = npcHandler, text = 'The rotten cyclopses whorship the raging giant of hell.'})
keywordHandler:addKeyword({'edron'}, StdModule.say, {npcHandler = npcHandler, text = 'This isle is rumoured to have been the home of a powerful ancient race which became extinct before the corpsewars. It was up to King Tibianus III to reclaim it for humanity and to found this colony.'})
keywordHandler:addKeyword({'minotaur'}, StdModule.say, {npcHandler = npcHandler, text = 'The minotaurs, though evil, were worthy opponents. After the treason of the man who is now known as Kaine Kinslayer, we lack the manpower to crush their cyclopean allies, too.'})
keywordHandler:addKeyword({'lunatic'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'shit'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'taboo'}, StdModule.say, {npcHandler = npcHandler, text = 'We thought it was only superstition and no one bothered that Kaine and his friends went there to hunt servants of evil that might have hidden there. So we did not notice the dark cult they started.'})
keywordHandler:addKeyword({'excalibug'}, StdModule.say, {npcHandler = npcHandler, text = 'With this weapon in my hand, I would teach the servants of darkness the true meaning of the word fear.'})
keywordHandler:addKeyword({'asshole'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'army'}, StdModule.say, {npcHandler = npcHandler, text = 'The army protects the Thaian realm. The order of the Knights of Banor\'s Blood supports them with all our skills.'})
keywordHandler:addKeyword({'general'}, StdModule.say, {npcHandler = npcHandler, text = 'Harkath Bloodblade declined the governorship because he\'s needed more in Thais.'})
keywordHandler:addKeyword({'join'}, StdModule.say, {npcHandler = npcHandler, text = 'You may join the order of Banor\'s blood if you prove your honor.'})
keywordHandler:addKeyword({'leader'}, StdModule.say, {npcHandler = npcHandler, text = 'King Tibianus III is our wise and just leader.'})
keywordHandler:addKeyword({'god'}, StdModule.say, {npcHandler = npcHandler, text = 'I worship Banor, the first champion of good!'})
keywordHandler:addKeyword({'banor'}, StdModule.say, {npcHandler = npcHandler, text = 'His spirit and blood are within us. Honor this fact or be cast into hell.'})
keywordHandler:addKeyword({'stupid'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'fuck'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'quest'}, StdModule.say, {npcHandler = npcHandler, text = 'A life in bravery, honor, and piety should be every man\'s most important quest.'})
keywordHandler:addKeyword({'ruins'}, StdModule.say, {npcHandler = npcHandler, text = 'An ancient taboo forbids to enter the northern ruins.'})
keywordHandler:addKeyword({'colony'}, StdModule.say, {npcHandler = npcHandler, text = 'With the Thaian army bound to other duties, our order was entrusted to secure the area. We defeated the evil minotaurs living right here and cleansed the isle of their unholy presence.'})
keywordHandler:addKeyword({'academy'}, StdModule.say, {npcHandler = npcHandler, text = 'After the treason of Kaine, we observe these mages closely. If even a knight falls prey to the seduction of the forbidden ruins, no one can tell how easy some of these mystics might betray his people.'})
keywordHandler:addKeyword({'fisherman'}, StdModule.say, {npcHandler = npcHandler, text = 'Pemaret is a fisherman on Cormaya.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I am the governor of this isle, Edron, and grandmaster of the Knights of Banor\'s Blood.'})
keywordHandler:addKeyword({'idiot'}, StdModule.say, {npcHandler = npcHandler, text = 'Take this!'})
keywordHandler:addKeyword({'enemies'}, StdModule.say, {npcHandler = npcHandler, text = 'Evil challenges the forces of good in any shape. Be it the claws of vicious monsters or the seductive dark secrets of rotten power.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'I am Sir Daniel Steelsoul of the Sacred Order of Banor\'s Blood.'})
keywordHandler:addKeyword({'agaltha'}, StdModule.say, {npcHandler = npcHandler, text = 'She was beautiful but seemed cold hearted. She spoke little to me, prefered the company of Kaine.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)

npcHandler:addModule(FocusModule:new())

